COMMIT;

CREATE GLOBAL TEMPORARY TABLE gtt_order_stage (
  order_id     NUMBER,
  customer_id  NUMBER,
  amount       NUMBER(10,2)
) ON COMMIT DELETE ROWS;

INSERT INTO gtt_order_stage (order_id, customer_id, amount)
SELECT order_id, customer_id, amount
  FROM orders
 WHERE status = 'PAID';

SELECT * FROM gtt_order_stage ORDER BY order_id;

CREATE GLOBAL TEMPORARY TABLE gtt_customer_totals (
  customer_id  NUMBER,
  order_count  NUMBER,
  total_amount NUMBER(12,2)
) ON COMMIT PRESERVE ROWS;

INSERT INTO gtt_customer_totals (customer_id, order_count, total_amount)
SELECT customer_id, COUNT(*), SUM(amount)
  FROM orders
 WHERE status = 'PAID'
 GROUP BY customer_id;

COMMIT;

SELECT * FROM gtt_customer_totals ORDER BY customer_id;

